import{_ as i,o as a,c as o,a2 as t}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Wiki 同步机制","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/wiki-sync.md","filePath":"zh/release/wiki-sync.md"}'),r={name:"zh/release/wiki-sync.md"};function l(s,e,d,n,c,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="wiki-同步机制" tabindex="-1">Wiki 同步机制 <a class="header-anchor" href="#wiki-同步机制" aria-label="Permalink to &quot;Wiki 同步机制&quot;">​</a></h1><p><code>tools/sync_wiki.sh</code>——docs/ 树同时活在 GitHub Wiki 上。</p><h2 id="同步什么" tabindex="-1">同步什么 <a class="header-anchor" href="#同步什么" aria-label="Permalink to &quot;同步什么&quot;">​</a></h2><p>Wiki 得到的是精选页面集（Home、Getting Started、Building、 Architecture Overview、Debugging &amp; QEMU、L1 Extension Guide、 User Manual、FAQ、Release Notes，外加各领域手册），由同一批 <code>docs/</code> 源渲染——一个写作面，两个输出（网站上的文档中心、 GitHub 上的 Wiki）。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>脚本把 <code>docs/</code> 页面映射到 Wiki 页面名（映射表在 脚本里）。</li><li>把相对链接改写为 Wiki 页面链接。</li><li>克隆 <code>{repo}.wiki</code>，写入页面，提交，推送。</li></ol><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><ul><li>每个被映射的 Wiki 页面都存在（脚本会打印清单）。</li><li>链接检查：映射集之内没有红链。</li><li>内容相等：Wiki 页面与文档页面渲染同一 份 markdown 源（脚本推送前会对它们做 diff）。</li></ul><h2 id="何时运行" tabindex="-1">何时运行 <a class="header-anchor" href="#何时运行" aria-label="Permalink to &quot;何时运行&quot;">​</a></h2><p>发布时（docs/ 变更落地之后），以及仅文档更新时按需 运行。</p>',10)])])}const _=i(r,[["render",l]]);export{u as __pageData,_ as default};
